    { position: "top-right", offsetX: 11, offsetY: 12, blankY: 13, zIndexBase: DEFAULT_UI_CONFIG.zIndexBase },
  );
  // #128 四角锚点透传 + zIndexBase clamp 边界（非法回退默认 / 越界压边界）。
  for (const p of ["top-left", "bottom-left"] as const) {
